  "LoadPokedexListPage": {
    returnType: "static bool8",
    params: "u8 page",
    callsTo: ["ARRAY_COUNT","AllocZeroed","BeginNormalPaletteFade","CopyBgTilemapBufferToVram","CopyToBgTilemapBuffer","CopyWindowToVram","CreateInterfaceSprites","CreateMonSpritesAtPos","CreatePokedexList","DeactivateAllTextPrinters","DecompressAndLoadBgGfxUsingHeap","FreeAllSpritePalettes","InitBgsFromTemplates","InitWindows","LoadCompressedSpriteSheet","LoadPokedexBgPalette","LoadSpritePalettes","PutWindowTilemap","ResetBgsAndClearDma3BusyFlags","ResetOtherVideoRegisters","ResetPaletteFade","ResetSpriteData","SetBgTilemapBuffer","SetGpuReg","SetVBlankCallback","ShowBg"],
    lineCount: 90,
    bodyC: "switch (gMain.state)\n    {\n    case 0:\n    default:\n        if (gPaletteFade.active)\n            return 0;\n        SetVBlankCallback(NULL);\n        sPokedexView->currentPage = page;\n        ResetOtherVideoRegisters(0);\n        SetGpuReg(REG_OFFSET_BG2VOFS, sPokedexView->initialVOffset);\n        ResetBgsAndClearDma3BusyFlags(0);\n        InitBgsFromTemplates(0, sPokedex_BgTemplate, ARRAY_COUNT(sPokedex_BgTemplate));\n        SetBgTilemapBuffer(3, AllocZeroed(BG_SCREEN_SIZE));\n        SetBgTilemapBuffer(2, AllocZeroed(BG_SCREEN_SIZE));\n        SetBgTilemapBuffer(1, AllocZeroed(BG_SCREEN_SIZE));\n        SetBgTilemapBuffer(0, AllocZeroed(BG_SCREEN_SIZE));\n        DecompressAndLoadBgGfxUsingHeap(3, gPokedexMenu_Gfx, 0x2000, 0, 0);\n        CopyToBgTilemapBuffer(1, gPokedexList_Tilemap, 0, 0);\n        CopyToBgTilemapBuffer(3, gPokedexListUnderlay_Tilemap, 0, 0);\n        if (page == PAGE_MAIN)\n            CopyToBgTilemapBuffer(0, gPokedexStartMenuMain_Tilemap, 0, 0x280);\n        else\n            CopyToBgTilemapBuffer(0, gPokedexStartMenuSearchResults_Tilemap, 0, 0x280);\n        ResetPaletteFade();\n        if (page == PAGE_MAIN)\n            sPokedexView->isSearchResults = FALSE;\n        else\n            sPokedexView->isSearchResults = TRUE;\n        LoadPokedexBgPalette(sPokedexView->isSearchResults);\n        InitWindows(sPokemonList_WindowTemplate);\n        DeactivateAllTextPrinters();\n        PutWindowTilemap(0);\n        CopyWindowToVram(0, COPYWIN_FULL);\n        gMain.state = 1;\n        break;\n    case 1:\n        ResetSpriteData();\n        FreeAllSpritePalettes();\n        gReservedSpritePaletteCount = 8;\n        LoadCompressedSpriteSheet(&sInterfaceSpriteSheet[0]);\n        LoadSpritePalettes(sInterfaceSpritePalette);\n        CreateInterfaceSprites(page);\n        gMain.state++;\n        break;\n    case 2:\n        gMain.state++;\n        break;\n    case 3:\n        if (page == PAGE_MAIN)\n            CreatePokedexList(sPokedexView->dexMode, sPokedexView->dexOrder);\n        CreateMonSpritesAtPos(sPokedexView->selectedPokemon, 0xE);\n        sPokedexView->menuIsOpen = FALSE;\n        sPokedexView->menuY = 0;\n        CopyBgTilemapBufferToVram(0);\n        CopyBgTilemapBufferToVram(1);\n        CopyBgTilemapBufferToVram(2);\n        CopyBgTilemapBufferToVram(3);\n        gMain.state++;\n        break;\n    case 4:\n        BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);\n        SetVBlankCallback(VBlankCB_Pokedex);\n        gMain.state++;\n        break;\n    case 5:\n        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_ALL | WININ_WIN1_ALL);\n        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_ALL | WINOUT_WINOBJ_BG0 | WINOUT_WINOBJ_BG2 | WINOUT_WINOBJ_BG3 | WINOUT_WINOBJ_OBJ);\n        SetGpuReg(REG_OFFSET_WIN0H, 0);\n        SetGpuReg(REG_OFFSET_WIN0V, 0);\n        SetGpuReg(REG_OFFSET_WIN1H, 0);\n        SetGpuReg(REG_OFFSET_WIN1V, 0);\n        SetGpuReg(REG_OFFSET_BLDCNT, 0);\n        SetGpuReg(REG_OFFSET_BLDALPHA, 0);\n        SetGpuReg(REG_OFFSET_BLDY, 0);\n        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 | DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON | DISPCNT_OBJWIN_ON);\n        ShowBg(0);\n        ShowBg(1);\n        ShowBg(2);\n        ShowBg(3);\n        gMain.state++;\n        break;\n    case 6:\n        if (!gPaletteFade.active)\n        {\n            gMain.state = 0;\n            return TRUE;\n        }\n        break;\n    }\n    return FALSE;",
  },
